# Transform function for task-c1f1ea96
# Pattern: Fill hollow boxes based on size parity
# - Odd size boxes → fill with 7
# - Even size boxes → fill with 2

def transform(grid):
    """Transform grid by filling hollow boxes based on size parity rule."""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find all hollow boxes
    boxes = []
    for outline_color in range(10):
        for r in range(h):
            for c in range(w):
                if grid[r][c] == outline_color:
                    max_r, max_c = r, c
                    for rr in range(r, h):
                        if grid[rr][c] != outline_color:
                            break
                        max_r = rr
                    for cc in range(c, w):
                        if grid[r][cc] != outline_color:
                            break
                        max_c = cc

                    size = max_r - r + 1
                    if 3 <= size <= 30:
                        is_hollow = True
                        for rr in range(r+1, max_r):
                            for cc in range(c+1, max_c):
                                if grid[rr][cc] == outline_color:
                                    is_hollow = False
                                    break
                            if not is_hollow:
                                break
                        if is_hollow:
                            boxes.append({'r': r, 'c': c, 'max_r': max_r, 'max_c': max_c, 'size': size})

    # Fill based on size parity
    for box in boxes:
        fill = 7 if box['size'] % 2 == 1 else 2
        for rr in range(box['r']+1, box['max_r']):
            for cc in range(box['c']+1, box['max_c']):
                result[rr][cc] = fill

    return result
